package GeneratedModel {
  private import ScalarValues::*;
  part def Controller {
    in attribute io_1 : Boolean;
    in attribute io_2 : Boolean;
    in attribute io_3 : Boolean;
    attribute processComplete : Boolean := false;
    attribute elapsed_stage1_ms : Integer := 0;
    attribute elapsed_stage2_ms : Integer := 0;
    attribute elapsed_stage3_ms : Integer := 0;
    attribute countdown_display : Integer := 0;
    attribute buzzer_hz : Integer := 0;
    perform action tick {
      first start;
      then if not processComplete {
        first start;
        then assign processComplete := false;
        then assign countdown_display := 0;
        then assign buzzer_hz := 0;
        then assign elapsed_stage1_ms := 0;
        then assign elapsed_stage2_ms := 0;
        then assign elapsed_stage3_ms := 0;
      }
    }
    out attribute io_0 : Integer = countdown_display;
    out attribute io_4 : Integer = buzzer_hz;
    out attribute io_5 : Boolean = processComplete;
    out attribute serial_0_trigger : Boolean = processComplete;
    out attribute serial_0_value_0 : Integer = elapsed_stage1_ms;
    out attribute serial_0_value_1 : Integer = elapsed_stage2_ms;
    out attribute serial_0_value_2 : Integer = elapsed_stage3_ms;
  }
  part system : Controller;
}
